import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·22","description":"易小帖 - 卷三·22","frontmatter":{"title":"卷三·22","description":"易小帖 - 卷三·22"},"headers":[],"relativePath":"zh/classics/yixiaotie/090.md","filePath":"zh/classics/yixiaotie/090.md"}'),o={name:"zh/classics/yixiaotie/090.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·22",tabindex:"-1"},[r("卷三·22 "),e("a",{class:"header-anchor",href:"#卷三·22","aria-label":"Permalink to “卷三·22”"},"​")],-1),e("p",null,"大衍之數夫子但言乾坤之策而不及六子，以揲蓍之法老變少不變。乾老陽，坤老陰，老則當變，故及之。若以二少言，則少陽數七，以四揲相乘，則四七二十八，每卦六爻，六其二十八則一百六十八也。少陰數八，以四揲相乘，則四八三十二數，每卦六爻，六其三十二，則一百九十二也。以一百六十八合之一百九十二，則猶是三百六十日當期之數，與乾坤無異，故震巽坎離艮兌六子雖老少不同，而其為三百六十策則八純皆同。故究推其極，則二篇之數，少陽策二十有八，凡一百九十二爻，為五千三百七十六策。少陰三十有二，凡一百九十二爻，為六千一百四十四策。合之亦萬有一千五百二十，當萬物之數，與乾坤二老之策無異。然其數亦止於此，若再推則又律歴家之事，非易義矣。宋劉牧受陳氏之教，然猶謂經惟舉乾坤二老三百六十之數，而不及他卦，疑卦氣直日之說為非是，況其他乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
